30	async function backendFavoriteSlugs(
31	  authToken: string
32	): Promise<string[] | null> {
33	  const page = await listFavoriteEventsExternal(authToken, 0, MAX_FAVORITES);
34	  if (!page) return null;
35	  return (page.content ?? [])
36	    .map((e) => e?.slug)
37	    .filter((s): s is string => typeof s === "string" && s.length > 0);
