40	export async function GET() {
41	  try {
42	    const authToken = await getValidAccessToken();
43	
44	    if (authToken) {
45	      const favorites = await backendFavoriteSlugs(authToken);
46	      if (favorites === null) {
47	        // Don't pretend the list is empty when the backend is unreachable —
48	        // an authed user with real favorites would see them disappear.
49	        return NextResponse.json(
50	          { ok: false, error: "BACKEND_ERROR" },
51	          { status: 502, headers: NO_STORE }
52	        );
53	      }
54	      return NextResponse.json(
55	        { ok: true, favorites },
56	        { headers: NO_STORE }
57	      );
58	    }
59	
60	    const favorites = await getFavoritesFromCookies();
61	    return NextResponse.json(
62	      { ok: true, favorites },
63	      { headers: NO_STORE }
64	    );
65	  } catch (error: unknown) {
66	    captureException(error, {
67	      tags: { feature: "favorites", route: "/api/favorites", method: "GET" },
68	    });
69	    return NextResponse.json(
70	      { ok: false, error: "INTERNAL" },
71	      { status: 500, headers: NO_STORE }
72	    );
73	  }
74	}
