76	export async function POST(request: Request) {
77	  try {
78	    let json: unknown;
79	    try {
80	      json = await request.json();
81	    } catch (error: unknown) {
82	      captureException(error, {
83	        tags: {
84	          feature: "favorites",
85	          route: "/api/favorites",
86	          method: "POST",
87	          phase: "parse_json",
88	        },
89	      });
90	      return NextResponse.json(
91	        { ok: false, error: "INVALID_BODY" },
92	        { status: 400, headers: NO_STORE }
93	      );
94	    }
95	
96	    const parsed = ToggleFavoriteSchema.safeParse(json);
97	    if (!parsed.success) {
98	      return NextResponse.json(
99	        { ok: false, error: "INVALID_BODY" },
100	        { status: 400, headers: NO_STORE }
101	      );
102	    }
103	
104	    const { eventSlug, eventId, shouldBeFavorite } = parsed.data;
105	    const authToken = await getValidAccessToken();
106	
107	    // Authenticated branch: backend is the source of truth.
108	    if (authToken) {
109	      if (!eventId) {
110	        // Falling back to the cookie path here would silently desync state:
111	        // the cookie write never reaches the backend and /preferits would
112	        // read an empty list for the user. Surface the bad request instead.
113	        return NextResponse.json(
114	          { ok: false, error: "EVENT_ID_REQUIRED" },
115	          { status: 400, headers: NO_STORE }
116	        );
117	      }
118	      const result = shouldBeFavorite
119	        ? await addFavoriteEventExternal(authToken, eventId)
120	        : await removeFavoriteEventExternal(authToken, eventId);
121	
122	      if (!result.ok && result.status === 409) {
123	        return NextResponse.json(
124	          {
125	            ok: false,
126	            error: "MAX_FAVORITES_REACHED",
127	            maxFavorites: MAX_FAVORITES,
128	            analyticsEvent: "favorites_limit_reached",
129	            analyticsParams: {
130	              action: shouldBeFavorite ? "add" : "remove",
131	              max_favorites: MAX_FAVORITES,
132	            },
133	          },
134	          { status: 409, headers: NO_STORE }
135	        );
136	      }
137	
138	      if (!result.ok) {
139	        return NextResponse.json(
140	          { ok: false, error: "BACKEND_ERROR" },
141	          { status: result.status || 502, headers: NO_STORE }
142	        );
143	      }
144	
145	      // Don't re-fetch the full list here: the client optimistically
146	      // updated the toggled button, and SWR revalidates the shared list via
147	      // GET on its own cadence. Returning early saves a second backend
148	      // round-trip on every toggle (the GET handler is the canonical list).
149	      return NextResponse.json({ ok: true }, { headers: NO_STORE });
150	    }
151	
152	    // Guest branch: cookie store, keyed by slug.
153	    const currentFavorites = await getFavoritesFromCookies();
154	    const nextSet = new Set(currentFavorites);
155	
156	    if (shouldBeFavorite) {
157	      if (!nextSet.has(eventSlug) && nextSet.size >= MAX_FAVORITES) {
158	        return NextResponse.json(
159	          {
160	            ok: false,
161	            error: "MAX_FAVORITES_REACHED",
162	            maxFavorites: MAX_FAVORITES,
163	            analyticsEvent: "favorites_limit_reached",
164	            analyticsParams: {
165	              action: "add",
166	              max_favorites: MAX_FAVORITES,
167	            },
168	          },
169	          { status: 409, headers: NO_STORE }
170	        );
171	      }
172	
173	      nextSet.delete(eventSlug);
174	      nextSet.add(eventSlug);
175	    } else {
176	      nextSet.delete(eventSlug);
177	    }
178	
179	    const nextFavorites = Array.from(nextSet);
180	    const persistedFavorites = await persistFavoritesCookie(nextFavorites);
181	
182	    return NextResponse.json(
183	      { ok: true, favorites: persistedFavorites },
184	      { headers: NO_STORE }
185	    );
186	  } catch (error: unknown) {
187	    captureException(error, {
188	      tags: { feature: "favorites", route: "/api/favorites", method: "POST" },
189	    });
190	    return NextResponse.json(
191	      { ok: false, error: "INTERNAL" },
192	      { status: 500, headers: NO_STORE }
193	    );
194	  }
195	}
