29	export async function listFavoriteEventsExternal(
30	  accessToken: string,
31	  page = 0,
32	  size = 50
33	): Promise<FavoriteEventsPageDTO | null> {
34	  const base = favoritesBaseUrl();
35	  if (!base) return null;
36	
37	  try {
38	    const query = new URLSearchParams({
