1	import { cache } from "react";
2	import { cookies } from "next/headers";
3	import { MAX_FAVORITES } from "@utils/constants";
4	
5	export const FAVORITES_COOKIE_NAME = "user_favorites";
6	export { MAX_FAVORITES };
7	
8	const MAX_AGE_SECONDS = 60 * 60 * 24 * 365;
9	
10	export function parseFavoritesCookie(raw: string | undefined): string[] {
11	  if (!raw) return [];
12	
13	  try {
14	    const parsed = JSON.parse(raw) as unknown;
15	    if (!Array.isArray(parsed)) return [];
16	
17	    return parsed
18	      .filter((value): value is string => typeof value === "string")
19	      .map((value) => value.trim())
20	      .filter(Boolean)
21	      .slice(0, MAX_FAVORITES);
22	  } catch {
23	    return [];
24	  }
25	}
26	
27	export const getFavoritesFromCookies = cache(async (): Promise<string[]> => {
28	  const cookieStore = await cookies();
29	  const currentCookie = cookieStore.get(FAVORITES_COOKIE_NAME);
30	  return parseFavoritesCookie(currentCookie?.value);
31	});
32	
33	export async function persistFavoritesCookie(
34	  favorites: string[]
35	): Promise<string[]> {
36	  const safe = favorites.slice(0, MAX_FAVORITES);
37	  const cookieStore = await cookies();
38	
39	  if (safe.length === 0) {
40	    cookieStore.delete(FAVORITES_COOKIE_NAME);
41	    return safe;
42	  }
43	
44	  cookieStore.set(FAVORITES_COOKIE_NAME, JSON.stringify(safe), {
45	    path: "/",
46	    maxAge: MAX_AGE_SECONDS,
47	    sameSite: "lax",
48	    httpOnly: true,
49	    secure: process.env.NODE_ENV === "production",
50	  });
51	
52	  return safe;
53	}
