41	async function fetchFavoritesEvents(
42	  slugs: string[]
43	): Promise<{ events: EventSummaryResponseDTO[]; notFoundSlugs: string[] }> {
44	  const uniqueSlugs = Array.from(new Set(slugs)).slice(0, MAX_FAVORITES);
45	  const results: EventSummaryResponseDTO[] = [];
46	  const notFoundSlugs: string[] = [];
47	
48	  const reasonToString = (reason: unknown): string => {
49	    if (reason instanceof Error) return reason.message;
50	    if (typeof reason === "string") return reason;
51	
52	    try {
53	      return JSON.stringify(reason);
54	    } catch {
55	      return "unknown";
56	    }
57	  };
58	
59	  for (let i = 0; i < uniqueSlugs.length; i += FETCH_CONCURRENCY) {
60	    const chunk = uniqueSlugs.slice(i, i + FETCH_CONCURRENCY);
61	    const fetched = await Promise.allSettled(
62	      chunk.map((slug) => fetchEventBySlugWithStatus(slug))
63	    );
64	
65	    const failedFetches: Array<{ slug: string | undefined; reason: unknown }> =
66	      [];
67	
68	    for (let j = 0; j < fetched.length; j++) {
69	      const slug = chunk[j];
70	      const settled = fetched[j];
71	      if (settled.status !== "fulfilled") {
72	        failedFetches.push({ slug, reason: settled.reason });
73	        continue;
74	      }
75	
76	      const { event, notFound } = settled.value;
77	
78	      if (notFound && slug) {
79	        notFoundSlugs.push(slug);
80	      }
81	
82	      if (event != null) {
83	        results.push(event);
84	      }
85	    }
86	
87	    if (failedFetches.length > 0) {
88	      captureException(new Error("Favorites: fetch failures"), {
89	        tags: {
90	          feature: "favorites",
91	          page: "/preferits",
92	          phase: "fetch_event_by_slug",
93	        },
94	        extra: {
95	          failedCount: failedFetches.length,
96	          failedSlugs: failedFetches.map((f) => f.slug).filter(Boolean),
97	          failedReasons: failedFetches.map((f) => reasonToString(f.reason)),
98	        },
99	      });
100	    }
101	  }
102	
103	  return { events: results, notFoundSlugs };
104	}
