106	function collectExpiredEventKeys<K>(
107	  events: EventSummaryResponseDTO[],
108	  keyOf: (event: EventSummaryResponseDTO) => K | null | undefined
109	): K[] {
110	  return events.flatMap((event) => {
111	    const key = keyOf(event);
112	    if (!key) return [];
113	    if (isEventActive(event)) return [];
114	    return [key];
115	  });
116	}
