118	async function loadFavoritesData(): Promise<FavoritesData> {
119	  const authToken = await getAccessTokenFromCookies();
120	
121	  if (authToken) {
122	    // Authed: backend is the source of truth. Returns fully populated event
123	    // summaries, so we skip the slug-by-slug round trip the cookie path uses.
124	    const page = await listFavoriteEventsExternal(authToken, 0, MAX_FAVORITES);
125	    if (page === null) {
126	      // Backend is unreachable; refuse to render an empty list (which would
127	      // make the user think they have no favorites). Show an error state.
128	      return {
129	        events: [],
130	        uniqueFavoritesCount: 0,
131	        slugsToRemove: [],
132	        eventIdsToRemove: [],
133	        backendUnavailable: true,
134	      };
135	    }
136	
137	    const events = page.content ?? [];
138	    return {
139	      events,
140	      uniqueFavoritesCount:
141	        page.totalElements ??
142	        new Set(events.map((e) => e?.slug).filter(Boolean)).size,
143	      // No cookie slugs to prune, but expired favorites still linger in the
144	      // backend store forever unless we tell it to remove them. Only page 0
145	      // is fetched (MAX_FAVORITES-sized), so an account that already holds
146	      // more than MAX_FAVORITES rows (pre-existing data from before the cap
147	      // was enforced) can still have expired favorites beyond this page that
148	      // never get pruned — accepted gap, not reachable going forward since
149	      // the 409 cap blocks new accounts from ever exceeding MAX_FAVORITES.
150	      slugsToRemove: [],
151	      eventIdsToRemove: collectExpiredEventKeys(events, (e) => e.id),
152	      backendUnavailable: false,
153	    };
154	  }
155	
156	  const cookieSlugs = [...(await getFavoritesFromCookies())].reverse();
157	  const fetched = await fetchFavoritesEvents(cookieSlugs);
158	  const expiredSlugs = collectExpiredEventKeys(fetched.events, (e) => e.slug);
159	
160	  return {
161	    events: fetched.events,
162	    uniqueFavoritesCount: new Set(cookieSlugs).size,
163	    slugsToRemove: Array.from(
164	      new Set([...expiredSlugs, ...fetched.notFoundSlugs])
165	    ),
166	    eventIdsToRemove: [],
167	    backendUnavailable: false,
168	  };
169	}
