3	import { useEffect, useRef, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import { captureException } from "@sentry/nextjs";
6	
7	export default function FavoritesAutoPrune({
8	  slugsToRemove,
9	  eventIdsToRemove = [],
10	}: {
11	  slugsToRemove: string[];
12	  eventIdsToRemove?: string[];
13	}) {
14	  const [, startTransition] = useTransition();
15	  const didRunRef = useRef(false);
16	  const router = useRouter();
17	
18	  useEffect(() => {
19	    if (didRunRef.current) return;
20	    didRunRef.current = true;
21	
22	    const hasSlugs = slugsToRemove && slugsToRemove.length > 0;
23	    const hasEventIds = eventIdsToRemove && eventIdsToRemove.length > 0;
24	    if (!hasSlugs && !hasEventIds) return;
25	
26	    startTransition(async () => {
27	      try {
28	        const response = await fetch("/api/favorites/prune", {
29	          method: "POST",
30	          headers: { "Content-Type": "application/json" },
31	          body: JSON.stringify({ slugsToRemove, eventIdsToRemove }),
32	        });
33	
34	        if (response.ok) {
35	          router.refresh();
36	        }
37	      } catch (error: unknown) {
38	        // Best-effort cleanup: never block rendering, but report for debugging.
39	        captureException(error, {
40	          tags: { feature: "favorites", action: "auto-prune" },
41	          extra: {
42	            slugs_to_remove_count: slugsToRemove.length,
43	            slugs_to_remove_sample: slugsToRemove.slice(0, 20),
44	            event_ids_to_remove_count: eventIdsToRemove.length,
45	            event_ids_to_remove_sample: eventIdsToRemove.slice(0, 20),
46	          },
47	        });
48	
49	        if (process.env.NODE_ENV !== "production") {
50	          console.error("Failed to auto-prune favorites:", error);
51	        }
52	      }
53	    });
54	  }, [router, slugsToRemove, eventIdsToRemove]);
55	
56	  // No UI: this is a background cleanup.
57	  return null;
58	}
