118	  } catch (error: unknown) {
119	    captureException(error, {
120	      tags: { feature: "favorites", route: "/api/favorites/prune" },
121	    });
122	    return NextResponse.json(
123	      { ok: false, error: "INTERNAL" },
124	      { status: 500, headers: NO_STORE }
