4	export async function fetchWithHmac(
5	  url: string,
6	  options: RequestInit & { skipBodySigning?: boolean; timeout?: number } = {}
7	): Promise<Response> {
8	  // Signal dynamic rendering before accessing current time (required by cacheComponents)
9	  await connection();
10	  const timestamp = Date.now();
11	  let bodyToSign = "";
12	  let normalizedBody: BodyInit | null | undefined = options.body;
13	  let wasUrlSearchParams = false;
14	
15	  if (options.body) {
16	    if (typeof options.body === "string") {
17	      bodyToSign = options.body;
18	    } else if (options.body instanceof URLSearchParams) {
19	      // Convert URLSearchParams to string BEFORE signing and sending.
20	      // This ensures the client and server see the same string representation.
21	      bodyToSign = options.body.toString();
22	      normalizedBody = bodyToSign;
23	      wasUrlSearchParams = true;
24	    } else if (options.body instanceof FormData) {
25	      bodyToSign = "";
26	    } else {
27	      // To prevent signature mismatches, we must be explicit about supported body types.
28	      // The server middleware can only reliably read string bodies (for non-FormData requests).
29	      // Other types like Blobs or ArrayBuffers would lead to signature failures.
30	      throw new Error(
31	        `fetchWithHmac: Unsupported body type. Only string, URLSearchParams, and FormData are supported.`
32	      );
33	    }
34	  }
35	
36	  if (options.skipBodySigning) {
37	    bodyToSign = "";
38	  }
39	
40	  let urlObject: URL;
41	  try {
42	    urlObject = new URL(url);
43	  } catch {
44	    throw new Error(
45	      `[fetchWithHmac] Invalid URL: "${url}". Server-side API calls must use absolute URLs.`
46	    );
47	  }
48	  const pathAndQuery = urlObject.pathname + urlObject.search;
49	
50	  const method = options.method?.toUpperCase() || "GET";
51	
52	  const hmac = await generateHmac(bodyToSign, timestamp, pathAndQuery, method);
53	
54	  const headers = new Headers(options.headers);
55	  headers.set("x-timestamp", String(timestamp));
56	  headers.set("x-hmac", hmac);
57	
58	  // Note: The caller can provide an explicit 'x-visitor-id' header in
59	  // options.headers when needed (e.g., counting event detail views).
60	
61	  if (wasUrlSearchParams && !headers.has("content-type")) {
62	    headers.set(
63	      "content-type",
64	      "application/x-www-form-urlencoded;charset=UTF-8"
65	    );
66	  }
67	
68	  // Use the normalized body (URLSearchParams converted to string) to ensure
69	  // the server middleware reads the exact same string we signed.
70	
71	  // Always enforce no-store for security when no Next.js cache options are provided
72	  // This prevents caching of sensitive HMAC-signed requests
73	  const cacheOption = options.next ? undefined : "no-store";
74	
75	  // Default 10s timeout for serverless environments (prevents hanging)
76	  const timeoutMs = options.timeout ?? 10000;
77	  const controller = new AbortController();
78	  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
79	
80	  // Merge signals if caller provided one (AbortSignal.any available in Node 20+)
81	  const signal = options.signal
82	    ? AbortSignal.any([options.signal, controller.signal])
83	    : controller.signal;
84	
85	  try {
86	    return await fetch(url, {
87	      ...options,
88	      cache: cacheOption,
89	      method,
90	      body: normalizedBody,
91	      headers,
92	      signal,
93	    });
94	  } finally {
95	    clearTimeout(timeoutId);
96	  }
97	}
