25	 * build-time fallback. (In Edge middleware env follows Edge semantics; this app
26	 * runs middleware on the Node standalone server, so it reads runtime env there
27	 * too — but don't assume runtime override in a generic Edge context.)
28	 */
29	function apiUrlCandidates(): Array<[string, string | undefined]> {
30	  return [
31	    // .trim() guards against copy-paste whitespace in the deploy platform's env.
32	    ["API_URL", process.env.API_URL?.trim()],
33	    ["NEXT_PUBLIC_API_URL", process.env.NEXT_PUBLIC_API_URL?.trim()],
34	  ];
35	}
