39	 * `ftp:`) are rejected: a non-special scheme makes `new URL(v).origin` return the
40	 * string "null", which would break fetch and the CSP connect-src allowlist.
41	 */
42	function isHttpUrl(value: string): boolean {
43	  try {
44	    const { protocol } = new URL(value);
45	    return protocol === "http:" || protocol === "https:";
46	  } catch {
47	    return false;
48	  }
49	}
