51	// Warn at most once per unique (var, value): resolveApiUrl runs on the per-request
52	// path, so a persistent misconfig would otherwise flood logs on every request.
53	const _warnedApiUrls = new Set<string>();
54	
55	/**
56	 * First candidate that is a valid http(s) URL. Invalid values are skipped with a
57	 * warning that names the offending var, so a typo'd API_URL falls back to
58	 * NEXT_PUBLIC_API_URL instead of breaking every fetch; the JSON default is last.
59	 */
60	function resolveApiUrl(): string {
61	  for (const [name, value] of apiUrlCandidates()) {
62	    if (!value) continue;
63	    if (isHttpUrl(value)) return value;
64	    const warnKey = `${name}=${value}`;
65	    if (!_warnedApiUrls.has(warnKey)) {
66	      _warnedApiUrls.add(warnKey);
67	      console.warn(`[api-helpers] Invalid ${name} format:`, value);
68	    }
69	  }
70	  return DEFAULT_API_URL;
71	}
