133	export async function getInternalApiUrl(
134	  path: string,
135	  options: InternalOriginOptions = {},
136	): Promise<string> {
137	  const normalized = path.startsWith("/") ? path : `/${path}`;
138	
139	  // Priority 1: Try to get host from request headers (works in server components)
140	  // This ensures Vercel preview URLs are correctly resolved.
