166	  // Priority 2: Explicit internal hostname (bypasses public CDN/Cloudflare)
167	  const internalSiteUrl = process.env.INTERNAL_SITE_URL;
168	  if (internalSiteUrl) {
169	    try {
170	      return new URL(normalized, internalSiteUrl).toString();
171	    } catch (error) {
172	      console.warn(
173	        `[getInternalApiUrl] Invalid INTERNAL_SITE_URL "${internalSiteUrl}":`,
174	        error,
175	      );
176	    }
177	  }
178	
179	  // Priority 3: Vercel deployments (check before NEXT_PUBLIC_SITE_URL to ensure preview URLs work)
180	  // VERCEL_URL is provided at runtime and points to the exact deployment host.
181	  // It does not include the protocol.
182	  const vercelUrl =
183	    process.env.VERCEL_URL || process.env.NEXT_PUBLIC_VERCEL_URL || "";
184	  if (vercelUrl) {
185	    const origin = vercelUrl.startsWith("http")
186	      ? vercelUrl
