277	/**
278	 * Apply distance/radius filter to FetchEventsParams if coordinates are provided.
279	 * Centralizes the distance filter logic used across all event list pages.
280	 * @param params - The fetch params object to mutate
281	 * @param input - Location data (lat, lon, distance) - accepts numbers or strings for flexibility
282	 * @returns The same params object (for chaining if needed)
283	 */
284	export function applyDistanceToParams(
285	  params: FetchEventsParams,
286	  input: {
287	    lat?: number | string;
288	    lon?: number | string;
289	    distance?: number | string;
290	  },
291	): FetchEventsParams {
292	  // Parse lat/lon from string or number
293	  const lat =
294	    input.lat !== undefined
295	      ? typeof input.lat === "string"
296	        ? parseFloat(input.lat)
297	        : input.lat
298	      : undefined;
299	  const lon =
300	    input.lon !== undefined
301	      ? typeof input.lon === "string"
302	        ? parseFloat(input.lon)
303	        : input.lon
304	      : undefined;
305	
306	  // Only apply if both coordinates are valid numbers
307	  if (lat !== undefined && lon !== undefined && !isNaN(lat) && !isNaN(lon)) {
308	    const maybeRadius = distanceToRadius(input.distance);
309	    if (maybeRadius !== undefined) {
310	      params.radius = maybeRadius;
311	    }
312	    params.lat = lat;
313	    params.lon = lon;
314	  }
315	
316	  return params;
317	}
