package com.esdeveniments.backend.user.favorite.service.impl;

import com.esdeveniments.backend.event.dto.EventSummaryResponseDTO;
import com.esdeveniments.backend.event.entity.Event;
import com.esdeveniments.backend.event.enums.EventPeriod;
import com.esdeveniments.backend.event.mapper.EventMapper;
import com.esdeveniments.backend.event.repository.EventRepository;
import com.esdeveniments.backend.event.specification.EventSpecification;
import com.esdeveniments.backend.shared.dto.PagedResponseDTO;
import com.esdeveniments.backend.shared.util.ErrorConstants;
import com.esdeveniments.backend.shared.util.Utils;
import com.esdeveniments.backend.user.entity.User;
import com.esdeveniments.backend.user.favorite.entity.UserFavoriteEvent;
import com.esdeveniments.backend.user.favorite.repository.UserFavoriteEventRepository;
import com.esdeveniments.backend.user.favorite.service.UserFavoriteEventService;
import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Collection;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class UserFavoriteEventServiceImpl implements UserFavoriteEventService {

    private final UserFavoriteEventRepository repository;
    private final EventRepository eventRepository;
    private final EventMapper eventMapper;

    @Override
    @Transactional
    public void addFavorite(User user, UUID eventId) {
        Event event = eventRepository.findById(eventId)
                .orElseThrow(() -> new EntityNotFoundException(ErrorConstants.ERROR_EVENT_NOT_FOUND));
        if (repository.existsByUserIdAndEventId(user.getId(), eventId)) {
            return;
        }
        repository.save(UserFavoriteEvent.builder()
                .user(user)
                .event(event)
                .createdAt(LocalDateTime.now())
                .build());
    }

    @Override
    @Transactional
    public void removeFavorite(User user, UUID eventId) {
        repository.deleteByUserIdAndEventId(user.getId(), eventId);
    }

    @Override
    public PagedResponseDTO<EventSummaryResponseDTO> getFavoriteEvents(User user, EventPeriod period, Integer page, Integer size) {
        Specification<Event> spec = EventSpecification.byPeriod(period)
                .and(EventSpecification.isFavoritedBy(user.getId()));
        Page<Event> eventsPage = eventRepository.findAll(spec, PageRequest.of(page, size));
        List<EventSummaryResponseDTO> events = eventMapper.eventsToSummaryResponseDtoList(eventsPage.getContent());
        events.forEach(event -> event.setFavorite(true));
        return Utils.buildPagedResponse(events, page, size, eventsPage.getTotalElements(), eventsPage.getTotalPages(), eventsPage.isLast());
    }

    @Override
    public boolean isFavorite(User user, UUID eventId) {
        return user != null && eventId != null && repository.existsByUserIdAndEventId(user.getId(), eventId);
    }

    @Override
    public Set<UUID> findFavoriteEventIds(User user, Collection<UUID> eventIds) {
        if (user == null || eventIds == null || eventIds.isEmpty()) {
            return Set.of();
        }
        return repository.findFavoriteEventIdsByUserIdAndEventIdIn(user.getId(), eventIds);
    }

    @Override
    public void markFavorite(User user, EventSummaryResponseDTO event) {
        if (event == null) {
            return;
        }
        event.setFavorite(isFavorite(user, event.getId()));
    }

    @Override
    public void markFavorites(User user, List<EventSummaryResponseDTO> events) {
        if (events == null || events.isEmpty()) {
            return;
        }
        Set<UUID> eventIds = events.stream()
                .map(EventSummaryResponseDTO::getId)
                .filter(id -> id != null)
                .collect(Collectors.toSet());
        Set<UUID> favoriteEventIds = findFavoriteEventIds(user, eventIds);
        events.forEach(event -> event.setFavorite(favoriteEventIds.contains(event.getId())));
    }
}

