package com.esdeveniments.backend.user.favorite.controller;

import com.esdeveniments.backend.event.dto.EventSummaryResponseDTO;
import com.esdeveniments.backend.event.enums.EventPeriod;
import com.esdeveniments.backend.shared.dto.PagedResponseDTO;
import com.esdeveniments.backend.user.entity.User;
import com.esdeveniments.backend.user.favorite.dto.FavoriteStatusResponseDTO;
import com.esdeveniments.backend.user.favorite.service.UserFavoriteEventService;
import lombok.RequiredArgsConstructor;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.UUID;

@RestController
@RequiredArgsConstructor
@RequestMapping("/api/users/me/favorites/events")
public class UserFavoriteEventController {

    private final UserFavoriteEventService service;

    @GetMapping
    public PagedResponseDTO<EventSummaryResponseDTO> getFavoriteEvents(@AuthenticationPrincipal User user,
                                                                        @RequestParam EventPeriod period,
                                                                        @RequestParam(defaultValue = "0") Integer page,
                                                                        @RequestParam(defaultValue = "20") Integer size) {
        return service.getFavoriteEvents(user, period, page, size);
    }

    @PostMapping("/{eventId}")
    public void addFavorite(@AuthenticationPrincipal User user, @PathVariable UUID eventId) {
        service.addFavorite(user, eventId);
    }

    @DeleteMapping("/{eventId}")
    public void removeFavorite(@AuthenticationPrincipal User user, @PathVariable UUID eventId) {
        service.removeFavorite(user, eventId);
    }

    @GetMapping("/{eventId}")
    public FavoriteStatusResponseDTO isFavorite(@AuthenticationPrincipal User user, @PathVariable UUID eventId) {
        return new FavoriteStatusResponseDTO(service.isFavorite(user, eventId));
    }
}

