package com.esdeveniments.backend.user.favorite.repository;

import com.esdeveniments.backend.user.favorite.entity.UserFavoriteEvent;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.Collection;
import java.util.Set;
import java.util.UUID;

public interface UserFavoriteEventRepository extends JpaRepository<UserFavoriteEvent, UUID> {

    boolean existsByUserIdAndEventId(UUID userId, UUID eventId);

    @Modifying
    void deleteByUserIdAndEventId(UUID userId, UUID eventId);

    @Query("""
            SELECT favorite.event.id
            FROM UserFavoriteEvent favorite
            WHERE favorite.user.id = :userId
              AND favorite.event.id IN :eventIds
            """)
    Set<UUID> findFavoriteEventIdsByUserIdAndEventIdIn(@Param("userId") UUID userId,
                                                        @Param("eventIds") Collection<UUID> eventIds);
}

