102	export async function isFavoriteEventExternal(
103	  accessToken: string,
104	  eventId: string
105	): Promise<boolean | null> {
106	  if (!eventId || !eventId.trim()) return null;
107	  const base = favoritesBaseUrl();
108	  if (!base) return null;
109	
110	  try {
111	    const response = await fetchWithHmac(
112	      `${base}/${encodeURIComponent(eventId)}`,
113	      { headers: authHeaders(accessToken) }
114	    );
115	    if (!response.ok) {
116	      await logBackendError("isFavoriteEventExternal", response);
117	      return null;
118	    }
119	    const parsed = parseFavoriteStatus(await response.json());
120	    return parsed?.favorite ?? null;
121	  } catch (error) {
122	    console.error("isFavoriteEventExternal: failed", error);
123	    return null;
124	  }
125	}
