127	export async function addFavoriteEventExternal(
128	  accessToken: string,
129	  eventId: string
130	): Promise<MutationResultDTO> {
131	  if (!eventId || !eventId.trim()) return { ok: false, status: 0 };
132	  const base = favoritesBaseUrl();
133	  if (!base) return { ok: false, status: 0 };
134	
135	  try {
136	    const response = await fetchWithHmac(
137	      `${base}/${encodeURIComponent(eventId)}`,
138	      {
139	        method: "POST",
140	        headers: authHeaders(accessToken),
141	        skipBodySigning: true,
142	      }
143	    );
144	    if (!response.ok) {
145	      await logBackendError("addFavoriteEventExternal", response);
146	    }
147	    return { ok: response.ok, status: response.status };
148	  } catch (error) {
149	    console.error("addFavoriteEventExternal: failed", error);
150	    return { ok: false, status: 0 };
151	  }
152	}
