154	export async function removeFavoriteEventExternal(
155	  accessToken: string,
156	  eventId: string
157	): Promise<MutationResultDTO> {
158	  if (!eventId || !eventId.trim()) return { ok: false, status: 0 };
159	  const base = favoritesBaseUrl();
160	  if (!base) return { ok: false, status: 0 };
161	
162	  try {
163	    const response = await fetchWithHmac(
164	      `${base}/${encodeURIComponent(eventId)}`,
165	      {
166	        method: "DELETE",
167	        headers: authHeaders(accessToken),
168	        skipBodySigning: true,
169	      }
170	    );
171	    if (!response.ok) {
172	      await logBackendError("removeFavoriteEventExternal", response);
173	    }
174	    return { ok: response.ok, status: response.status };
