161	/**
162	 * Date range shortcuts that compute from/to dates client-side.
163	 * These populate from/to query params instead of byDate URL segments.
164	 */
165	function toYMD(d: Date): string {
166	  const parts = new Intl.DateTimeFormat("en", {
167	    timeZone: TIMEZONE_MADRID,
168	    year: "numeric",
169	    month: "2-digit",
170	    day: "2-digit",
171	  }).formatToParts(d);
172	  const y = parts.find((p) => p.type === "year")?.value ?? "";
173	  const m = parts.find((p) => p.type === "month")?.value ?? "";
174	  const day = parts.find((p) => p.type === "day")?.value ?? "";
175	  return `${y}-${m}-${day}`;
176	}
177	
178	/** Create a Date representing "now" in Madrid local time (avoids wrong day at tz boundaries). */
179	function nowInMadrid(): Date {
180	  const parts = new Intl.DateTimeFormat("en", {
181	    timeZone: TIMEZONE_MADRID,
182	    year: "numeric",
183	    month: "2-digit",
184	    day: "2-digit",
185	  }).formatToParts(new Date());
186	  const y = Number(parts.find((p) => p.type === "year")?.value);
187	  const m = Number(parts.find((p) => p.type === "month")?.value) - 1;
188	  const d = Number(parts.find((p) => p.type === "day")?.value);
189	  return new Date(y, m, d, 12, 0, 0);
190	}
