192	export const DATE_RANGE_SHORTCUTS: DateRangeShortcut[] = [
193	  {
194	    labelKey: "nextWeek",
195	    getRange: () => {
196	      const today = nowInMadrid();
197	      const dayOfWeek = today.getDay(); // 0=Sun
198	      const daysUntilNextMon = dayOfWeek === 0 ? 1 : 8 - dayOfWeek;
199	      const nextMon = new Date(today);
200	      nextMon.setDate(today.getDate() + daysUntilNextMon);
201	      const nextSun = new Date(nextMon);
202	      nextSun.setDate(nextMon.getDate() + 6);
203	      return { from: toYMD(nextMon), to: toYMD(nextSun) };
204	    },
205	  },
206	  {
207	    labelKey: "thisMonth",
208	    getRange: () => {
209	      const today = nowInMadrid();
210	      const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);
211	      return { from: toYMD(today), to: toYMD(lastDay) };
212	    },
213	  },
214	  {
215	    labelKey: "nextMonth",
216	    getRange: () => {
217	      const today = nowInMadrid();
218	      const firstDay = new Date(today.getFullYear(), today.getMonth() + 1, 1);
219	      const lastDay = new Date(today.getFullYear(), today.getMonth() + 2, 0);
220	      return { from: toYMD(firstDay), to: toYMD(lastDay) };
221	    },
222	  },
223	];
