3	import { useEffect, useRef, useState, useTransition } from "react";
4	import { useTranslations } from "next-intl";
5	import { useRouter } from "@i18n/routing";
6	import useSWR from "swr";
7	import { HeartIcon as HeartIconSolid } from "@heroicons/react/24/solid";
8	import { HeartIcon as HeartIconOutline } from "@heroicons/react/24/outline";
9	
10	import Button from "@components/ui/common/button";
11	import { sendGoogleEvent } from "@utils/analytics";
12	import useTrackedCta from "@components/hooks/useTrackedCta";
13	import { queueFavoriteRequest } from "@utils/favorites-queue";
14	import { useAuth } from "@components/hooks/useAuth";
15	import { GUEST_FAVORITE_SAVED_EVENT } from "@utils/favorites-events";
16	import type { FavoriteButtonProps } from "types/props";
17	import { captureException } from "@sentry/nextjs";
18	
19	const FAVORITES_SWR_KEY = "favorites:list";
20	
21	function parseMaxFavorites(payload: unknown): number | null {
22	  if (!payload || typeof payload !== "object") return null;
23	  const maybe = (payload as Record<string, unknown>).maxFavorites;
24	  return typeof maybe === "number" ? maybe : null;
25	}
26	
27	function isMaxReachedPayload(payload: unknown): boolean {
28	  if (!payload || typeof payload !== "object") return false;
29	  return (payload as Record<string, unknown>).error === "MAX_FAVORITES_REACHED";
30	}
31	
32	export default function FavoriteButton({
33	  eventSlug,
34	  eventId,
35	  eventTitle,
36	  initialIsFavorite,
37	  labels,
38	  className = "",
39	}: FavoriteButtonProps) {
40	  const [isFavorite, setIsFavorite] = useState(initialIsFavorite);
41	  const [limitMessage, setLimitMessage] = useState<string | null>(null);
42	  const [isPending, startTransition] = useTransition();
43	  const isMutatingRef = useRef(false);
44	  const router = useRouter();
45	  const { isAuthenticated } = useAuth();
46	  const t = useTranslations("Components.FavoriteButton");
47	  const { ref: ctaRef, trackClick } = useTrackedCta<HTMLDivElement>("favorite_button");
48	
49	  const { data: favoritesData, mutate: mutateFavorites } = useSWR<
50	    { ok: true; favorites: string[] } | { ok: false; error: string }
51	  >(
52	    FAVORITES_SWR_KEY,
53	    async () => {
54	      const res = await fetch("/api/favorites", { method: "GET" });
55	      if (!res.ok) throw new Error("Failed to fetch favorites");
56	      return res.json() as Promise<
57	        { ok: true; favorites: string[] } | { ok: false; error: string }
58	      >;
59	    },
60	    {
61	      revalidateOnFocus: false,
62	      revalidateOnReconnect: true,
63	      revalidateIfStale: true,
64	      dedupingInterval: 30_000,
65	    }
66	  );
67	
68	  useEffect(() => {
69	    if (isMutatingRef.current) return;
70	    if (!favoritesData || favoritesData.ok !== true) return;
71	    setIsFavorite(favoritesData.favorites.includes(eventSlug));
72	  }, [favoritesData, eventSlug]);
73	
74	  const ariaLabel = isFavorite ? labels.remove : labels.add;
75	  const Icon = isFavorite ? HeartIconSolid : HeartIconOutline;
76	
77	  return (
78	    <div ref={ctaRef} className="relative">
79	      <Button
80	        type="button"
81	        variant="ghost"
82	        className={["group p-2", className].filter(Boolean).join(" ")}
83	        aria-label={ariaLabel}
84	        aria-pressed={isFavorite}
85	        disabled={isPending}
86	        data-favorite-button
87	        onClick={(e) => {
88	          e.preventDefault();
89	          e.stopPropagation();
90	
91	          trackClick();
92	          setLimitMessage(null);
93	          const nextIsFavorite = !isFavorite;
94	          setIsFavorite(nextIsFavorite);
95	
96	          startTransition(async () => {
97	            isMutatingRef.current = true;
98	            try {
99	              const response = await queueFavoriteRequest(() =>
100	                fetch("/api/favorites", {
101	                  method: "POST",
102	                  headers: { "Content-Type": "application/json" },
103	                  body: JSON.stringify({
104	                    eventSlug,
105	                    eventId,
106	                    shouldBeFavorite: nextIsFavorite,
107	                  }),
108	                })
109	              );
110	
111	              if (!response.ok) {
112	                const payload = (await response.json().catch(() => null)) as unknown;
113	                if (response.status === 409 && isMaxReachedPayload(payload)) {
114	                  const max = parseMaxFavorites(payload);
115	                  sendGoogleEvent("favorites_limit_reached", {
116	                    action: "add",
117	                    max_favorites: max,
118	                    event_slug: eventSlug,
119	                    event_id: eventId,
120	                    event_title: eventTitle,
121	                  });
122	                  setLimitMessage(t("maxReached", { max: max ?? "" }));
123	                  setIsFavorite(!nextIsFavorite);
124	                  return;
125	                }
126	
127	                throw new Error("Failed to update favorites");
128	              }
129	
130	              const payload = (await response.json().catch(() => null)) as unknown;
131	              if (
132	                payload &&
133	                typeof payload === "object" &&
134	                "favorites" in payload &&
135	                Array.isArray((payload as { favorites?: unknown }).favorites)
136	              ) {
137	                // Guest cookie branch echoes the canonical list — adopt it.
138	                const favorites = (payload as { favorites: unknown[] }).favorites
139	                  .filter((value): value is string => typeof value === "string")
140	                  .map((value) => value.trim())
141	                  .filter(Boolean);
142	
143	                mutateFavorites({ ok: true, favorites }, { revalidate: false });
144	              } else {
145	                // Authed branch returns `{ ok: true }` only (one less round
146	                // trip per toggle). Keep cross-instance SWR consumers in
147	                // sync by updating the cache locally with the same change
148	                // the backend just persisted.
149	                mutateFavorites(
150	                  (current) => {
151	                    if (!current || current.ok !== true) return current;
152	                    const set = new Set(current.favorites);
153	                    if (nextIsFavorite) set.add(eventSlug);
154	                    else set.delete(eventSlug);
155	                    return { ok: true, favorites: Array.from(set) };
156	                  },
157	                  { revalidate: false }
158	                );
159	              }
160	
161	              const analyticsEventName = nextIsFavorite
162	                ? "favorite_add"
163	                : "favorite_remove";
164	
165	              sendGoogleEvent(analyticsEventName, {
166	                event_slug: eventSlug,
167	                event_id: eventId,
168	                event_title: eventTitle,
169	              });
170	
171	              // Guest just saved a favorite (kept in the cookie until they
172	              // log in). Nudge them — once per session — to sign in so it
173	              // syncs. The session-level FavoriteLoginNudge owns the UI and
174	              // the once-per-session guard; we only emit the signal.
175	              if (nextIsFavorite && !isAuthenticated) {
176	                window.dispatchEvent(new Event(GUEST_FAVORITE_SAVED_EVENT));
177	              }
178	
179	              // Preserve existing /preferits UX: reflect removals immediately.
180	              // Avoid refreshing other pages to keep the toggle lightweight.
181	              if (window.location.pathname.endsWith("/preferits")) {
182	                router.refresh();
183	              }
