23	// Format bytes to human readable
24	function formatBytes(bytes) {
25	  if (bytes === 0) return '0 B';
26	  const k = 1024;
27	  const sizes = ['B', 'KB', 'MB', 'GB'];
28	  const i = Math.floor(Math.log(bytes) / Math.log(k));
29	  return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
30	}
