32	// Get file size
33	function getFileSize(filePath) {
34	  try {
35	    const stats = statSync(filePath);
36	    return stats.size;
37	  } catch {
38	    return 0;
39	  }
40	}
41	
42	// Recursively get all files in directory
43	function getAllFiles(dir, fileList = []) {
44	  try {
45	    const files = readdirSync(dir, { withFileTypes: true });
46	    for (const file of files) {
47	      const filePath = join(dir, file.name);
48	      if (file.isDirectory()) {
49	        getAllFiles(filePath, fileList);
50	      } else if (file.isFile()) {
51	        fileList.push(filePath);
52	      }
53	    }
54	  } catch {
55	    // Ignore errors
56	  }
57	  return fileList;
58	}
