60	// Analyze client bundles
61	function analyzeClientBundles() {
62	  const staticDir = join(projectRoot, '.next', 'static');
63	  const chunksDir = join(staticDir, 'chunks');
64	  
65	  if (!statSync(chunksDir, { throwIfNoEntry: false })) {
66	    return [];
67	  }
68	
69	  const files = getAllFiles(chunksDir);
70	  const bundles = files
71	    .filter(f => f.endsWith('.js') || f.endsWith('.css'))
72	    .map(file => {
73	      const size = getFileSize(file);
74	      const relativePath = file.replace(projectRoot + '/', '');
75	      return {
76	        path: relativePath,
77	        size,
78	        type: file.endsWith('.css') ? 'CSS' : 'JS',
79	      };
80	    })
81	    .filter(b => b.size > 0)
82	    .sort((a, b) => b.size - a.size);
83	
84	  return bundles;
85	}
