87	// Analyze server bundles for a specific route
88	function analyzeRouteServerBundle(route) {
89	  const appServerDir = join(projectRoot, '.next', 'server', 'app');
90	  const routePath = route.replace(/^\//, '');
91	  const serverDir = route === '/' ? join(appServerDir, 'page') : join(appServerDir, routePath);
92	
93	  const rootFiles = [];
94	  if (route === '/') {
95	    try {
96	      const entries = readdirSync(appServerDir, { withFileTypes: true });
97	      for (const entry of entries) {
98	        if (!entry.isFile()) continue;
99	        if (!entry.name.startsWith('page.')) continue;
100	        const filePath = join(appServerDir, entry.name);
101	        rootFiles.push(filePath);
102	      }
103	    } catch {
104	      // Ignore
105	    }
106	  }
107	
108	  if (!statSync(serverDir, { throwIfNoEntry: false }) && rootFiles.length === 0) {
109	    return null;
110	  }
111	
112	  const files = [...rootFiles, ...getAllFiles(serverDir)];
113	  const bundles = files
114	    .filter(f => f.endsWith('.js') || f.endsWith('.json'))
115	    .map(file => {
116	      const size = getFileSize(file);
117	      const relativePath = file.replace(projectRoot + '/', '');
118	      const fileName = file.split('/').pop();
119	      return {
120	        path: relativePath,
121	        fileName,
122	        size,
123	        type: file.endsWith('.json') ? 'JSON' : 'JS',
124	      };
125	    })
126	    .filter(b => b.size > 0)
127	    .sort((a, b) => b.size - a.size);
128	
129	  const totalSize = bundles.reduce((sum, b) => sum + b.size, 0);
130	  
131	  return {
132	    route,
133	    bundles,
134	    totalSize,
135	    fileCount: bundles.length,
136	  };
137	}
