147	    try {
148	      const manifestFile = join(projectRoot, '.next', 'server', 'app-paths-manifest.json');
149	      const content = readFileSync(manifestFile, 'utf-8');
150	      const manifest = JSON.parse(content);
151	
152	      const routes = Object.keys(manifest)
153	        .map((key) => {
154	          if (key === '/page') return '/';
155	          if (key.endsWith('/page')) return key.replace(/\/page$/, '');
156	          if (key.endsWith('/route')) return key.replace(/\/route$/, '');
157	          return null;
158	        })
159	        .filter(Boolean);
160	
161	      // De-dupe while preserving stable ordering
162	      return Array.from(new Set(routes));
163	    } catch {
164	      // Last resort: try to discover routes from .next/server/app directories
165	      const appDir = join(projectRoot, '.next', 'server', 'app');
166	      if (!statSync(appDir, { throwIfNoEntry: false })) {
167	        return [];
168	      }
169	
170	      const routes = [];
171	      function discoverRoutes(dir, prefix = '') {
172	        try {
173	          const entries = readdirSync(dir, { withFileTypes: true });
174	          for (const entry of entries) {
175	            if (entry.isDirectory()) {
176	              const routePath = prefix + '/' + entry.name;
177	              const pageFile = join(dir, entry.name, 'page.js');
178	              const routeFile = join(dir, entry.name, 'route.js');
179	
180	              if (statSync(pageFile, { throwIfNoEntry: false })) {
181	                routes.push(routePath === '/page' ? '/' : routePath);
182	              }
183	              if (statSync(routeFile, { throwIfNoEntry: false })) {
184	                routes.push(routePath.replace(/\/(route)$/, ''));
185	              }
186	
187	              discoverRoutes(join(dir, entry.name), routePath);
188	            }
189	          }
