45	async function fetchFavoritesEvents(
46	  slugs: string[]
47	): Promise<{ events: EventSummaryResponseDTO[]; notFoundSlugs: string[] }> {
48	  const uniqueSlugs = Array.from(new Set(slugs)).slice(0, MAX_FAVORITES);
49	  const results: EventSummaryResponseDTO[] = [];
50	  const notFoundSlugs: string[] = [];
51	
52	  const reasonToString = (reason: unknown): string => {
53	    if (reason instanceof Error) return reason.message;
54	    if (typeof reason === "string") return reason;
55	
56	    try {
57	      return JSON.stringify(reason);
58	    } catch {
59	      return "unknown";
60	    }
61	  };
62	
63	  for (let i = 0; i < uniqueSlugs.length; i += FETCH_CONCURRENCY) {
64	    const chunk = uniqueSlugs.slice(i, i + FETCH_CONCURRENCY);
65	    const fetched = await Promise.allSettled(
66	      chunk.map((slug) => fetchEventBySlugWithStatus(slug))
67	    );
68	
69	    const failedFetches: Array<{ slug: string | undefined; reason: unknown }> =
70	      [];
71	
72	    for (let j = 0; j < fetched.length; j++) {
73	      const slug = chunk[j];
74	      const settled = fetched[j];
75	      if (settled.status !== "fulfilled") {
76	        failedFetches.push({ slug, reason: settled.reason });
77	        continue;
78	      }
79	
80	      const { event, notFound } = settled.value;
81	
82	      if (notFound && slug) {
83	        notFoundSlugs.push(slug);
84	      }
85	
86	      if (event != null) {
87	        results.push(event);
88	      }
89	    }
90	
91	    if (failedFetches.length > 0) {
92	      captureException(new Error("Favorites: fetch failures"), {
93	        tags: {
94	          feature: "favorites",
95	          page: "/preferits",
96	          phase: "fetch_event_by_slug",
97	        },
98	        extra: {
99	          failedCount: failedFetches.length,
100	          failedSlugs: failedFetches.map((f) => f.slug).filter(Boolean),
101	          failedReasons: failedFetches.map((f) => reasonToString(f.reason)),
102	        },
103	      });
104	    }
105	  }
106	
107	  return { events: results, notFoundSlugs };
108	}
